llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Naltrexone, the closest structural analogue, has an oral bioavailability of only ~5% in healthy male volunteers due to extensive first-pass hepatic metabolism; this low-F result transfers to the query because the query is the N-methyl quaternary derivative of the same morphinan scaffold and should be even less permeable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A separate study estimated systemic bioavailability of a single oral naltrexone dose at only 5-6% in healthy volunteers, independently confirming low oral F in the closest structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Morphine-6-glucuronide, a polar morphinan metabolite, has poor oral bioavailability and is given intravenously; this supports the principle that adding polar/charged character to the morphinan opioid scaffold markedly lowers oral F, consistent with the query's permanent quaternary ammonium.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "One naltrexone study reported 60% oral bioavailability, but this is an outlier among multiple low-F reports and is poorly transferable to the query because the query's permanent positive charge introduces a major absorption barrier absent in naltrexone.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nalmefene, a tertiary-amine morphinan antagonist, has an absolute oral bioavailability of 41%, but it lacks the permanent positive charge of the query; this high-F evidence is contradictory but has limited transferability because quaternary ammonium compounds are poorly membrane-permeable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C24"],
      "claim": "Samidorphan, another tertiary-amine morphinan, shows 69% oral bioavailability, but the absence of a permanent charge and different polarity limit transfer to the quaternary query; this does not outweigh the low-F evidence from closer analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is methylnaltrexone, a quaternary ammonium morphinan. The closest analogue naltrexone has predominantly low oral bioavailability (often ~5-6%, with most reports below or near 20%) due to first-pass metabolism, and the permanent positive charge of the query further impairs passive permeability and absorption. High-F tertiary-amine analogues such as nalmefene and samidorphan are less transferable because they lack the quaternary charge. Therefore, F >= 20% is not supported; predict low.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for methylnaltrexone is present in the provided evidence set.",
    "Naltrexone oral bioavailability reports are highly variable (5-60%), creating uncertainty in the exact magnitude of the parent scaffold's F.",
    "No experimental data specifically isolate the effect of quaternization on oral F in this morphinan scaffold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

